import 'package:flutter_gcaptcha_v3/flutter_gcaptcha_v3.dart';

final controller = GCaptchaController();

GCaptchaWebView(
  controller: controller,
  siteKey: 'YOUR_SITE_KEY',
  url: 'https://yourdomain.com/index.html',
);

// Later, after execute:
String token = await controller.getCaptchaToken();
